def upsert_email_template(template):
    if frappe.db.exists("Email Template", template["name"]):
        doc = frappe.get_doc("Email Template", template["name"])
        doc.subject = template["subject"]
        doc.response = template["response"]
        doc.use_html = 1
        doc.save(ignore_permissions=True)
    else:
        frappe.get_doc({
            "doctype": "Email Template",
            "name": template["name"],
            "subject": template["subject"],
            "response": template["response"],
            "use_html": 1
        }).insert(ignore_permissions=True)


def seed_email_templates():
    for template in TEMPLATES:
        try:
            upsert_email_template(template)
            print(f"✅ Synced: {template['name']}")
        except Exception as e:
            frappe.log_error(frappe.get_traceback(), f"Email Template Error: {template['name']}")
            print(f"❌ Failed: {template['name']} -> {str(e)}")

            print("🚀 All staffing email templates processed")